output.arguments:
{"command":"set +e
for case in nocode badout missingfile parsererr; do
 rm -rf /tmp/home_$case; mkdir /tmp/home_$case /tmp/w_$case; cd /tmp/w_$case; printf 'x\n' > f.txt
 echo "\n## $case"
 case $case in
  nocode) HOME=/tmp/home_$case /workspace/executable -o x.svg >out 2>err;;
  badout) HOME=/tmp/home_$case /workspace/executable -f f.txt -o x.jpg >out 2>err;;
  missingfile) HOME=/tmp/home_$case /workspace/executable -f nope -o x.svg >out 2>err;;
  parsererr) HOME=/tmp/home_$case /workspace/executable --type bad -o x.svg >out 2>err;;
 esac
 rc=$?; echo rc=$rc; echo stdout:; cat out; echo stderr:; cat err; find /tmp/home_$case -type f -printf '%p\n'
done
"}

